# Cisco white paper on MLPerf Inference v5.1 and v6.1 with the UCS C845A M8, held against the v5.1 and v6.1 result files. python3 -I check_claims_cisco_c845a_v61.py
import json,hashlib,re
FILES=['raw/inf_5.1.json','raw/inf_6.1.json']; RAW={f:open(f,'rb').read() for f in FILES}
V1=json.loads(RAW[FILES[0]]); B=list(json.loads(RAW[FILES[1]]).values()); s=str
def mk(i,q,calc,st,got,out,note): return dict(id=i,quote=q,calc=calc,stated=st,delivered=got,outcome=out,note=note,label_mismatch=False)
def n(x):
    m=re.findall(r'\(x(\d+)\)',s(x.get('Accelerator'))); return sum(map(int,m)) if m else int(x.get('a#') or 0)*int(x.get('Nodes') or 1)
C5=[x for x in V1 if x['Submitter']=='Cisco' and 'C845A' in x['System']]; C6=[x for x in B if x['Organization']=='Cisco' and 'C845A' in x['SystemName']]
CC=[]
h200=[x for x in C5 if 'H200-NVL' in s(x['Accelerator']) and n(x)==8]; l40=[x for x in C5 if 'L40S' in s(x['Accelerator']) and n(x)==8]; r6=[x for x in C6 if 'RTX PRO 6000' in s(x['accelerator_model_name']) and x['total_accelerators']==8]; r45=[x for x in C6 if 'RTX PRO 4500' in s(x['accelerator_model_name']) and x['total_accelerators']==8]
CC.append(mk('CC1','Inference 5.1 and 6.1: Datacenter performance was measured on a Cisco UCS C845A M8 Rack Server equipped with 8 NVIDIA H200 NVL GPUs, 8 NVIDIA L40S PCIe GPUs and 8 NVIDIA RTX PRO 6000 and RTX PRO 4500 PCIe GPUs.','Cisco C845A M8 entries in the v5.1 and v6.1 files','four eight-GPU configurations',f'v5.1: H200 NVL {len(h200)} rows, L40S {len(l40)} rows. v6.1: RTX PRO 6000 {len(r6)} rows, RTX PRO 4500 {len(r45)} rows','CONSISTENT' if h200 and l40 and r6 and r45 else 'BELOW',''))
mods5=sorted({x['Model'] for x in C5})
CC.append(mk('CC2','Cisco has tested most of the datasets listed in Table 1 on the Cisco UCS C845A M8 Rack Server and submitted the results to MLCommons','C845A M8 models in the v5.1 file against the seven models in Table 1 of the post','most of seven models submitted',f'{len(mods5)} of 7 models in v5.1: {mods5}','CONSISTENT' if len(mods5)>=4 else 'BELOW','The post then marks the Llama 2 70B, Stable Diffusion XL and Whisper results as collected after the deadline and not verified. The file holds only Llama 3.1 8B and Retinanet for this server.'))
l2=[x for x in C5 if x['Model'].startswith('llama2')]; wh=[x for x in C5 if x['Model']=='whisper']; sd=[x for x in C5 if 'diffusion' in x['Model']]; l45=[x for x in r45 if x['Model'].startswith('llama2')]
CC.append(mk('CC3','Note: For Llama2-70b performance data, the results have not been verified by MLCommons Association because the results were collected after the MLPerf submission deadline. ... Note: For NVIDIA RTX PRO 4500 Llama2-70b performance data, the results have not been verified by MLCommons Association because the results were collected after the MLPerf submission deadline.','C845A M8 entries in the v5.1 and v6.1 files for Llama 2 70B, Stable Diffusion XL and Whisper on H200 NVL, and Llama 2 70B on RTX PRO 4500','these results are not published entries',f'v5.1 C845A rows: Llama 2 70B {len(l2)}, Whisper {len(wh)}, Stable Diffusion XL {len(sd)}. v6.1 RTX PRO 4500 Llama 2 70B rows: {len(l45)}','CONSISTENT' if not (l2 or wh or sd or l45) else 'BELOW','None of the unverified results are entries in the file, which is what the notes say.'))
g=[x for x in C6 if x['Model']=='gpt-oss-120b']
CC.append(mk('CC4','Figure 16 shows the performance of the gpt-oss-120b model tested on a Cisco UCS C880A M8 Rack Server with 8x NVIDIA RTX PRO 6000 GPUs.','Cisco gpt-oss-120b entries with eight RTX PRO 6000 in the v6.1 file, system name','C880A M8 with 8 RTX PRO 6000',', '.join(sorted({x["SystemName"][:44] for x in g if x["total_accelerators"]==8 and "RTX PRO 6000" in s(x["accelerator_model_name"])}))+'; the C880A M8 entries in the file use B300','CONSISTENT' if any('C880A' in x['SystemName'] and 'RTX' in s(x['accelerator_model_name']) for x in B if x['Organization']=='Cisco') else 'BELOW','The figure title in the post says C845A and the sentence says C880A. The file names the eight RTX PRO 6000 entry C845A M8.'))
def rk5(m,sc,f):
    me=[x for x in h200 if x['Model']==m and x['Scenario']==sc][0]; g_=[x for x in V1 if x['Category']=='closed' and 'datacenter' in x['Suite'] and x['Model']==m and x['Scenario']==sc and s(x['Accelerator'])==s(me['Accelerator']) and n(x)==n(me)]
    return 1+sum(1 for x in g_ if x['Performance_Result']>me['Performance_Result']),len(g_)
def rk6(sysn,m,sc):
    me=[x for x in C6 if sysn in x['SystemName'] and x['Model']==m and x['Scenario']==sc][0]; g_=[x for x in B if x['Division']=='closed' and x['Availability']=='available' and x['Model']==m and x['Scenario']==sc and s(x['accelerator_model_name'])==s(me['accelerator_model_name']) and x['total_accelerators']==me['total_accelerators']]
    return 1+sum(1 for x in g_ if x['Result']>me['Result']),len(g_)
t=lambda L:', '.join(f'{sc} {r}/{nn}' for sc,(r,nn) in L)
a=[(sc,rk5('llama3.1-8b',sc,None)) for sc in('Offline','Server')]; b_=[(sc,rk5('retinanet',sc,None)) for sc in('Offline','Server')]
c=[('Server',rk6('RTXPro6000','llama2-70b-99.9','Server')),('Offline',rk6('RTXPro6000','llama2-70b-99.9','Offline'))]
d=[(sc,rk6('RTX PRO 4500','llama3.1-8b',sc)) for sc in('Interactive','Offline','Server')]; e=[('Offline',rk6('RTX PRO 4500','whisper','Offline'))]
RULE='Our rank rule: entries with the same accelerator model and count, higher result first. Overall among all closed entries for the model and scenario the rank is lower.'
first=lambda L:all(r==1 for sc,(r,nn) in L)
CC.append(mk('CC5','The Cisco UCS C845A M8 platform with 8x NVIDIA H200 NVL GPUs emerged as the leader, securing first position for the Llama3.1-8b model.','Cisco 5.1-0011 against closed datacenter v5.1 entries with eight H200 NVL','first for Llama 3.1 8B',t(a)+'; the only eight H200 NVL entry for this model','CONSISTENT' if first(a) else 'BELOW',RULE+' Cisco is the only entry in this group, so first holds by the absence of others.'))
CC.append(mk('CC6','The Cisco UCS C845A M8 platform with 8x NVIDIA H200 NVL GPUs emerged as the leader, securing first position for the Retinanet model.','Cisco 5.1-0011 against closed datacenter v5.1 entries with eight H200 NVL','first for Retinanet',t(b_),'CONSISTENT' if first(b_) else 'BELOW',RULE+' First holds in Server and not in Offline.'))
CC.append(mk('CC7','The Cisco UCS C845A M8 platform with 8x NVIDIA RTX PRO 6000 GPUs emerged as the leader, securing first position for the Llama2-70b model for Server scenario','Cisco C845A RTX PRO 6000 llama2-70b-99.9 against closed available v6.1 entries with eight RTX PRO 6000','first for Llama 2 70B Server',t(c),'CONSISTENT' if c[0][1][0]==1 else 'BELOW',RULE+' The file has the 99.9 variant for this server. Offline is second.'))
CC.append(mk('CC8','The Cisco UCS C845A M8 platform with 8x NVIDIA RTX PRO 4500 GPUs emerged as the leader, securing first position for the Llama3.1-8b model.','Cisco C845A RTX PRO 4500 llama3.1-8b against closed available v6.1 entries with eight RTX PRO 4500','first for Llama 3.1 8B',t(d),'CONSISTENT' if first(d) else 'BELOW',RULE+' Cisco is the only entry in this group, so first holds by the absence of others.'))
CC.append(mk('CC9','The Cisco UCS C845A M8 platform with 8x NVIDIA RTX PRO 4500 GPUs emerged as the leader, securing first position for the Whisper model.','Cisco C845A RTX PRO 4500 whisper against closed available v6.1 entries with eight RTX PRO 4500','first for Whisper',t(e),'CONSISTENT' if first(e) else 'BELOW',RULE+' Cisco is the only entry in this group, so first holds by the absence of others.'))
h5=C5[0]; h6=C6[0]
CC.append(mk('CC10','CPU 2x AMD EPYC 9575 64-Core Processor Number of cores 64','Cisco C845A entries in the v5.1 and v6.1 files, host processor fields','2 x AMD EPYC 9575, 64 cores',f'v5.1 {h5["host_processors_per_node"]} x {h5["Processor"]}, {h5["host_processor_core_count"]} cores. v6.1 {h6["host_processors_per_node"]} x {h6["host_processor_model_name"]}, {h6["host_processor_core_count"]} cores','CONSISTENT' if 'EPYC 9575' in s(h6['host_processor_model_name']) else 'BELOW','The v5.1 entries list EPYC 9575F with 64 cores. The v6.1 entries list EPYC 9655 with 96 cores. Table 2 in the post gives one CPU for both rounds.'))
json.dump(dict(source=FILES,sha256=[hashlib.sha256(RAW[f]).hexdigest() for f in FILES],claims=CC),open('claims_cisco_c845a_v61.json','w'),indent=1)
for c_ in CC: print(c_['id'],c_['outcome'],'|',c_['stated'][:48],'|',c_['delivered'][:240])
